Object.assign(RU,{hardwareControls:'REC: сразу вкл/выкл. SEQ + EDIT: удалить шаг. SEQ + REC: очистить партию. Удерживая SEQ, чёрная 11 очищает всю дорожку. На FM-1: SELECT всегда BPM · ALGO: дорожка · кнопка повторно: страница. Удержание + HOME: LOCK. SEQ + OCT−/+: банк. EDIT + OCT−/+: Undo/Redo. На дорожке 6 K2 выбирает ударный; SEQ + клавиша меняет только его.'});Object.assign(EN,{hardwareControls:'REC toggles immediately. SEQ + EDIT erases a step; SEQ + REC clears a part. Hold SEQ + black key 11 to clear a track. FM-1: SELECT always BPM · ALGO: track · tap the same button: page. Hold + HOME: LOCK. SEQ + OCT−/+: bank. EDIT + OCT−/+: Undo/Redo. Track 6 K2 selects a drum; SEQ + key toggles only that drum.'});
const dictionaries={ru:RU,en:EN};
let lang='ru';try{lang=localStorage.getItem('zcore-language')||'ru';}catch{}if(!dictionaries[lang])lang='ru';
const tr=k=>dictionaries[lang][k]||EN[k]||k;
const status=(s,error=false)=>{$('status').textContent=s;$('status').classList.toggle('error',error);};
const schema=await (await fetch('./schema.json')).json();
const module=await WebAssembly.compile(await (await fetch('./zombie-core.wasm?v=110')).arrayBuffer());
const local=new WebAssembly.Instance(module,{}).exports;local.z_init();
const DRAFT_KEY=new URLSearchParams(location.search).has('scratch')?'zcore-groovebox-137-scratch':'zcore-groovebox-137-v3';
const memory=()=>new Uint8Array(local.memory.buffer,local.z_snapshot(),STATE_BYTES);
const patternHistory=new PatternHistory();let soloTrack=0,nativeUndo=0,nativeRedo=0;
let state=decodeState(memory().slice()),busy=false,tab='sound',bank=0,selectedStep=0,octave=60,loadedWav=null,playing=false,midiAccess;
state.drums=wasmDrums(local);
let editingUntil=0,pointerEditing=false,controlCounter=0,lastPresetTrack=-1,lastPresetId=-1,syncErrors=0;
const isEditing=()=>pointerEditing||performance.now()<editingUntil||held.size>0;
document.addEventListener('input',()=>{editingUntil=performance.now()+450;});
document.addEventListener('pointerdown',e=>{if(e.target.matches('input,select'))pointerEditing=true;});
document.addEventListener('pointerup',()=>{pointerEditing=false;editingUntil=performance.now()+250;});
document.addEventListener('pointercancel',()=>{pointerEditing=false;});
window.addEventListener('blur',()=>{pointerEditing=false;});
const userSamples=new Map(),held=new Map(),computerHeld=new Map();
const link=new Link(()=>{soloTrack=0;patternHistory.reset(state);renderConnection();renderHistory();});
function persistDraft(){try{const draft=structuredClone(state);draft.recording=0;localStorage.setItem(DRAFT_KEY,JSON.stringify(draft));}catch{}}
function acceptAudio(bytes){const next=decodeState(bytes);state.tracks.forEach((t,i)=>{t.steps=next.tracks[i].steps;t.p[23]=next.tracks[i].p[23];});state.recording=next.recording;state.stepEdit=next.stepEdit;state.bank=next.bank;bank=state.bank;selectedStep=state.stepEdit;patternHistory.observe(state,true);persistDraft();renderHistory();$('record').setAttribute('aria-pressed',String(!!state.recording));renderSteps();}
