function drawWave(){const c=$('waveform'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!loadedWav)return;ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue('--accent');ctx.beginPath();const pcm=loadedWav.pcm;for(let x=0;x<c.width;x++){const a=Math.floor(x*pcm.length/c.width),b=Math.max(a+1,Math.floor((x+1)*pcm.length/c.width));let lo=1,hi=-1;for(let i=a;i<b;i++){lo=Math.min(lo,pcm[i]);hi=Math.max(hi,pcm[i]);}ctx.moveTo(x,75+lo*65);ctx.lineTo(x,75+hi*65);}ctx.stroke();}
$('wav-file').onchange=()=>run(async()=>{const file=$('wav-file').files[0];if(!file)return;if(file.size>64*1024*1024)throw Error('WAV > 64 MiB');loadedWav=wavPCM(await file.arrayBuffer());$('trim-start').value=0;$('trim-end').value=Math.min(loadedWav.pcm.length/loadedWav.rate,24400/Number($('sample-rate').value)).toFixed(3);$('sample-info').textContent=`${file.name} · ${(loadedWav.pcm.length/loadedWav.rate).toFixed(3)} ${tr('sampleSeconds')} ${loadedWav.rate} Hz`;$('sample-preview').disabled=false;renderConnection();drawWave();status(tr('done'));});
function region(){if(!loadedWav)throw Error(tr('sampleFirst'));const start=Number($('trim-start').value),end=Number($('trim-end').value),rate=Number($('sample-rate').value);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>loadedWav.pcm.length/loadedWav.rate+.001)throw Error('Invalid trim range');const first=Math.floor(start*loadedWav.rate),last=Math.min(loadedWav.pcm.length,Math.floor(end*loadedWav.rate));if(Math.floor((last-first)*rate/loadedWav.rate)>24448)throw Error(tr('sampleTooLong'));return {pcm:resamplePCM(loadedWav.pcm.slice(first,last),loadedWav.rate,rate),rate,slot:Number($('sample-slot').value)};}
async function installPreview(s){await audio.start();samplerUI.resend();samplerUI.sample(s.slot,s.pcm,s.rate);userSamples.set(s.slot,s);sync();audio.send('sample',{slot:s.slot,pcm:s.pcm,rate:s.rate});}
$('sample-preview').onclick=()=>run(async()=>{const s=region();await installPreview(s);const preview=structuredClone(state),t=state.selected;preview.tracks[t].p[0]=8;preview.tracks[t].p[19]=6+s.slot;preview.tracks[t].p[4]=127;preview.tracks[t].p[8]=127;preview.tracks[t].p[20]=60;samplerUI.audition(t);audio.send('state',{bytes:encodeState(preview)});audio.send('note',{track:t,note:60,velocity:100,on:1});setTimeout(()=>{audio.send('note',{track:t,note:60,velocity:0,on:0});sync();samplerUI.resend();},s.pcm.length/s.rate*1000+50);status(tr('done'));});
$('sample-upload').onclick=()=>run(async()=>{if(!link.connected)throw Error(tr('deviceOnly'));const s=region();await changeTransport(false);await link.upload(s.slot,s.pcm,s.rate,p=>{$('sample-progress').value=p;});userSamples.set(s.slot,s);samplerUI.sample(s.slot,s.pcm,s.rate);audio.send('sample',{slot:s.slot,pcm:s.pcm,rate:s.rate});await setParam(state.selected,0,8);await setParam(state.selected,19,6+s.slot);await setParam(state.selected,20,60);await samplerUI.assign(6+s.slot);await refreshSlots();status(`${tr('sampleLoaded')}${s.slot+1}.`);});
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status(tr('downloaded'));}
$('export-project').onclick=()=>download('zombie-core-project.json',state);
async function applyProject(next){next=validateState(next,schema);next.drums??=migrateDrums(next);encodeDrums(next.drums);await changeTransport(false);if(link.connected){const bytes=encodeState(next,!link.modern?true:link.live?false:2);await link.command(16,u32(crc32(bytes)));try{for(let i=0;i<bytes.length;i+=192)await link.command(17,[...u16(i),...bytes.slice(i,i+192)]);await link.command(18);await uploadDrums(next.drums);}catch(e){await link.command(14).catch(()=>{});throw e;}}state=structuredClone(next);state.recording=0;patternHistory.reset(state);lang=state.language?'en':'ru';bank=state.bank;selectedStep=state.stepEdit;sync();render();keyboard();}
$('import-project').onchange=()=>run(async()=>{const f=$('import-project').files[0];if(!f)return;if(f.size>200000)throw Error('Project too large');const next=validateState(JSON.parse(await f.text()),schema);await applyProject(next);status(tr('projectLoaded'));});
$('export-patch').onclick=()=>download('zombie-core-sound.json',{format:'zombie-core-patch/1',p:state.tracks[state.selected].p});
$('import-patch').onchange=()=>run(async()=>{const f=$('import-patch').files[0];if(!f)return;if(f.size>20000)throw Error('Patch too large');const patch=JSON.parse(await f.text());if(patch.format!=='zombie-core-patch/1')throw Error('Invalid patch');const next=structuredClone(state);next.tracks[next.selected].p=patch.p;validateState(next,schema);await applyProject(next);status(tr('patchLoaded'));});
function showPosition(position){if(state.selected===5){document.querySelectorAll(".dm-grid [data-step]").forEach(b=>b.classList.toggle("playhead",playing&&Number(b.dataset.step)===drumPositions[Number(b.dataset.drum)]));return;}pianoHead=playing?position:-1;drawPianoRoll($('piano-roll'),state,selectedStep,bank,pianoHead);const at=playing?position%state.tracks[state.selected].p[23]:0;$('position-display').textContent=`${String(Math.floor(at/16)+1).padStart(2,'0')} : ${String(at%16+1).padStart(2,'0')}`;document.querySelectorAll('#step-grid button').forEach(b=>b.classList.toggle('playhead',playing&&Number(b.dataset.index)===position%state.tracks[state.selected].p[23]));}
function setTab(next){const changed=tab!==next;tab=next;document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==tab);document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===next)));drawGraphs();if(changed)animatePanel($(tab));}
async function setPanel(id,value){
 if(link.connected&&!link.modern&&![0,3,5].includes(id))throw Error(tr('syncOld'));
 if(link.connected&&link.modern)await link.command(21,[id,value]);
 if(id===0)state.octave=value-3;else if(id===1){state.section=value;state.subpage=0;}else if(id===2)state.subpage=value;else if(id===3){state.bank=value;state.stepEdit=value*16+state.stepEdit%16;}else if(id===4)state.recording=value;else if(id>=9&&id<=13)state[(["recMode","recQuant","metronome","fxAmount","fxRate"])[id-9]]=value;else if(id===5){state.stepEdit=value;state.bank=Math.floor(value/16);}
 sync();
}
function renderArp(){const t=state.selected,a=state.arp[t];$('arp-controls').replaceChildren(...['mode','rate','octaves','hold'].map((key,i)=>{const label=document.createElement('label'),span=document.createElement('span'),input=document.createElement('select');span.textContent=tr(['arpMode','arpRate','arpOctaves','arpHold'][i]);const options=i===0?[tr('off'),lang==='ru'?'Вверх':'Up',lang==='ru'?'Вниз':'Down',lang==='ru'?'Туда-обратно':'Up/down',lang==='ru'?'Случайно':'Random']:i===1?['1/8','1/16','1/32','1/8T']:i===2?['1','2','3']:[tr('off'),tr('on')];options.forEach((name,j)=>input.add(new Option(name,i===2?String(j+1):String(j))));input.value=a[key];input.setAttribute('aria-label',span.textContent);input.onchange=()=>perform(async()=>{const value=Number(input.value);if(link.connected){if(!link.modern)throw Error(tr('syncOld'));await link.command(22,[t,i,value]);}state.arp[t][key]=value;sync();});label.append(span,input);return label;}));}
function acceptState(next){next=validateState(next,schema);next.drums??=state.drums;syncErrors=0;
 const changed=JSON.stringify(next)!==JSON.stringify(state),sectionChanged=next.section!==state.section||(next.section===5&&next.subpage!==state.subpage);
 if(changed){state=next;lang=state.language?'en':'ru';bank=state.bank;selectedStep=state.stepEdit;try{localStorage.setItem('zcore-language',lang);}catch{}sync(true);render();keyboard();if(sectionChanged&&!(tab==='live'&&state.section===1))setTab(state.section===5&&state.subpage===3?'samples':({0:'sound',1:'sound',2:'mixer',3:'sound',4:'sound',5:'sound',6:'settings',7:'sequence',8:'sequence'})[state.section]);}
}
const deviceSync=new DeviceSync(link,{onState:acceptState,onHealthy:()=>{syncErrors=0;if(tab==='samples'&&!isEditing())samplerUI.poll();},onRuntime:r=>{if(r.drumPositions)drumPositions=r.drumPositions;nativeUndo=r.undo;nativeRedo=r.redo;const soloChanged=soloTrack!==r.solo;soloTrack=r.solo;renderHistory();if(soloChanged)renderLiveTracks();playing=r.playing;$('play').setAttribute('aria-pressed',String(playing));document.querySelectorAll('#live-pads button').forEach((b,i)=>b.setAttribute('aria-pressed',String(r.effect===i+1)));$('record').setAttribute('aria-pressed',String(!!r.recording));showPosition(r.position);const section=(lang==='ru'?['Главная','Эффекты','Дорожка','Огибающая','LFO','Синтез','Настройки','Арпеджиатор','Шаги']:['Home','FX','Track','Envelope','LFO','Synth','Settings','Arpeggiator','Steps'])[r.section];$('sync-status').textContent=`${tr('syncLive')} · ${section} · OCT ${r.octave>=0?'+':''}${r.octave} · ${r.dirty?'●':'✓'}${r.layer>=0?' · HOLD':''}`;},onError:e=>{status(e.message,true);if(++syncErrors>=3){link.close();syncErrors=0;}},isBusy:()=>busy||document.hidden,isEditing});
deviceSync.start();
$('record').onclick=()=>perform(async()=>{if(!state.recording&&!link.connected){if(state.selected===5){drumLocal();local.z_dm_checkpoint();}else patternHistory.checkpoint(state);}await setPanel(4,state.recording?0:1);$('record').setAttribute('aria-pressed',String(!!state.recording));if(state.recording)setTab('sequence');});
window.addEventListener('pagehide',()=>{deviceSync.stop();releaseKeys();releasePads();link.close();audio.close();});
const padHeld=new Map();
const fxNames=['DUCK','CHOP','TREMOLO','BITS','DRIVE','MONO','SWAP','PUMP','RING','BOOST','RIGHT','LEFT','GATE','FUZZ','PHASE','CUT'];
function setEffect(effect){audio.send('live',{effect});if(link.connected&&link.live)perform(()=>link.command(23,[effect]));}
function releasePads(){padHeld.clear();document.querySelectorAll('#live-pads button').forEach(b=>b.setAttribute('aria-pressed','false'));setEffect(0);}
function renderLiveSettings(){
 for(const [id,key] of [['rec-mode','recMode'],['rec-quant','recQuant'],['metronome','metronome'],['fx-amount','fxAmount'],['fx-rate','fxRate']]){const el=$(id);if(el)el.value=state[key];}
}
fxNames.forEach((name,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0')+' / '+name;b.setAttribute('aria-pressed','false');b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);padHeld.set(e.pointerId,{effect:i+1,b});b.setAttribute('aria-pressed','true');setEffect(i+1);};b.onpointerup=b.onpointercancel=b.onlostpointercapture=e=>{if(!padHeld.delete(e.pointerId))return;b.setAttribute('aria-pressed','false');setEffect([...padHeld.values()].at(-1)?.effect||0);};$('live-pads').append(b);});
for(const [id,num] of [['rec-mode',9],['rec-quant',10],['metronome',11],['fx-amount',12],['fx-rate',13]])$(id).onchange=()=>perform(async()=>{if(link.connected&&!link.live)throw Error('Install Zombie Core 0.17.0');await setPanel(num,Number($(id).value));});
let taps=[];$('tap-tempo').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2000)taps=[];if(taps.length&&now-taps.at(-1)<200)return;taps.push(now);taps=taps.slice(-5);if(taps.length>1){$('tempo').value=Math.max(30,Math.min(300,Math.round(60000*(taps.length-1)/(now-taps[0]))));$('tempo').onchange();}};
window.addEventListener('blur',releasePads);document.addEventListener('visibilitychange',()=>{if(document.hidden)releasePads();});
$('undo').onclick=()=>perform(()=>restorePattern(false));$('redo').onclick=()=>perform(()=>restorePattern(true));
$('duplicate-pattern').onclick=()=>perform(()=>patternAction(1));$('shift-left').onclick=()=>perform(()=>patternAction(2));$('shift-right').onclick=()=>perform(()=>patternAction(3));$('reverse-pattern').onclick=()=>perform(()=>patternAction(5));
$('copy-pattern').onclick=()=>perform(()=>patternAction(4,Number($('copy-target').value)));
$('copy-target').replaceChildren(...Array.from({length:6},(_,i)=>new Option(String(i+1),String(i))));$('copy-target').value='1';
async function toggleStep(at=selectedStep){if(state.recording)throw Error(lang==='ru'?'Выключи REC перед редактированием шага.':'Turn REC off before editing a step.');const s=state.tracks[state.selected].steps[at];s.velocity=s.velocity?0:100;await writeStep(state.selected,at);renderSteps();}
$('toggle-step').onclick=()=>perform(()=>toggleStep());
$('preset-search').oninput=()=>{const q=$('preset-search').value.trim().toLowerCase(),old=$('preset').value;const matches=PRESETS.map((name,i)=>({name,i})).filter(p=>p.name.toLowerCase().includes(q));$('preset').replaceChildren(...matches.map(p=>new Option(p.name,String(p.i))));if(matches.some(p=>String(p.i)===old))$('preset').value=old;$('load-preset').disabled=!matches.length;};
document.addEventListener('keydown',e=>{if(e.ctrlKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();perform(()=>restorePattern(e.key.toLowerCase()==='y'||e.shiftKey));}});
try{const draft=JSON.parse(localStorage.getItem(DRAFT_KEY));if(draft){state=validateState(draft,schema);state.recording=0;state.arp.forEach(a=>a.hold=0);state.drums??=migrateDrums(state);drumLocal();bank=state.bank;selectedStep=state.stepEdit;}}catch{}
state.language=lang==='ru'?0:1;sync();render();keyboard();initInterface();status(tr('ready'));


bindPianoRoll($('piano-roll'),{getState:()=>state,getSelected:()=>selectedStep,getBank:()=>bank,status,
 select:at=>perform(async()=>{await setPanel(5,at);selectedStep=at;bank=Math.floor(at/16);renderSteps();}),
 edit:change=>perform(async()=>{if(state.recording)throw Error(lang==='ru'?'Сначала выключи REC.':'Stop REC before editing.');const {at,note,duration,add,remove}=change,s=state.tracks[state.selected].steps[at];selectedStep=at;await setPanel(5,at);
 if(change.clear){s.velocity=0;s.chord=[0,0,0];s.duration=0;}
 else if(change.toggle)s.velocity=s.velocity?0:100;
 else if(remove||change.click&&s.velocity&&[s.note,...s.chord.filter(Boolean).map(n=>n-1)].includes(note)){if(s.note===note){const chord=s.chord.filter(Boolean);if(chord.length){s.note=chord.shift()-1;s.chord=[...chord,0,0,0].slice(0,3);}else s.velocity=0;}else s.chord=s.chord.map(n=>n===note+1?0:n);}
 else if((add||change.click)&&s.velocity&&note!==s.note){if(!s.chord.includes(note+1)){const i=s.chord.indexOf(0);if(i<0)throw Error('Max 4 notes per step');s.chord[i]=note+1;}}
 else{s.note=note;s.velocity=s.velocity||100;}if(duration!==null)s.duration=duration;await writeStep(state.selected,at);renderSteps();})});
setTab('sequence');

function drumLocal(){const b=encodeDrums(state.drums);new Uint8Array(local.memory.buffer,local.z_dm_data(),b.length).set(b);memory().set(encodeState(state));}
async function uploadDrums(drums){const b=encodeDrums(drums);await link.command(47,u32(crc32(b)));for(let i=0;i<b.length;i+=192)await link.command(17,[...u16(i),...b.slice(i,i+192)]);await link.command(48);}
function renderDrumKit(){const drum=state.selected===5;document.querySelectorAll('#sequence [data-i="recordHelp"],#sequence [data-i="pianoHelp"],#sequence [data-i="seqHelp"],#sequence [data-i="arpeggiator"],#sequence .pattern-actions,#sequence h3:not(#drum-kit h3)').forEach(e=>e.hidden=drum);$('length').parentElement.hidden=drum;$('seq-controls').hidden=drum;$('copy-pattern').disabled=drum;const kit=state.selected===5;document.body.dataset.drumKit=String(kit);for(const id of ['model','preset','preset-search','load-preset'])$(id).disabled=kit;$('drum-kit').hidden=!kit;if(!kit)return;state.drums??=migrateDrums(state);$('copy-pattern').disabled=kit;
 if([...held.values()].some(h=>h.t===5))return;
 renderDrums({root:$('drum-kit'),state,bank,language:lang,
 select:d=>perform(async()=>{state.drums.selected=d;if(link.connected)await link.command(42,[d]);sync();renderDrumKit();}),
 hit:(note,d,id)=>{const b=$('drum-kit');held.set('drum'+id,{n:note,t:5,button:b});audio.send('note',{track:5,note,velocity:110,on:1});if(link.connected)perform(()=>link.command(4,[5,note,110,1]));},release:id=>keyUp('drum'+id),
 step:(d,at,v)=>perform(async()=>{await setPanel(5,at);drumLocal();local.z_dm_step(d,at,v.velocity,v.chance,v.ratchet);state.drums=wasmDrums(local);state.drums.selected=d;if(link.connected){await link.command(42,[d]);await link.command(45,[d,at,v.velocity,v.chance,v.ratchet]);}sync();renderDrumKit();renderHistory();}),
 param:(d,field,value)=>perform(async()=>{const f=['level','decay','tune','pan','mute','length'].indexOf(field);drumLocal();local.z_dm_param(d,f,value);state.drums=wasmDrums(local);if(link.connected)await link.command(44,[d,f,...u16(value)]);sync();renderDrumKit();renderHistory();})});}

